import{_ as n,a0 as d,w as u,s as a,ao as l,I as r,x as s,a1 as t,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const c=JSON.parse(`{"title":"Linux有問必答時間：怎樣解決“XXX is not in the sudoers file”錯誤 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有問必答時間：怎樣解決“XXX is not in the sudoers file”錯誤 | LCTT (201503) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有問必答時間：怎樣解決“XXX is not in the sudoers file”錯誤 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有問必答時間：怎樣解決“XXX is not in the sudoers file”錯誤 | LCTT (201503) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201503/20141224 Linux FAQs with Answers--How to fix 'XXX is not in the sudoers file' error","title":"Linux有問必答時間：怎樣解決“XXX is not in the sudoers file”錯誤","tag":"201503","desc":""},"relativePath":"201503/20141224 Linux FAQs with Answers--How to fix 'XXX is not in the sudoers file' error.md","filePath":"[post].md"}`),p={name:"201503/20141224 Linux FAQs with Answers--How to fix 'XXX is not in the sudoers file' error.md"};function f(h,e,x,m,X,L){const o=d("Link");return u(),a("div",null,[e[11]||(e[11]=l(`<h1 id="linux有問必答時間-怎樣解決-xxx-is-not-in-the-sudoers-file-錯誤" tabindex="-1">Linux有問必答時間：怎樣解決“XXX is not in the sudoers file”錯誤 <a class="header-anchor" href="#linux有問必答時間-怎樣解決-xxx-is-not-in-the-sudoers-file-錯誤" aria-label="Permalink to “Linux有問必答時間：怎樣解決“XXX is not in the sudoers file”錯誤”">​</a></h1><blockquote><p><strong>問題</strong>:我想在我的Linux系統上使用sudo來運行一些特權命令，然而當我試圖這麼做時，我卻得到了&quot;[我的用户名] is not in the sudoers file. This incident will be reported.&quot;的錯誤信息。我該怎麼處理這種sudo錯誤呢？</p></blockquote><p>sudo是一個允許特定的用户組用另一個用户(典型的是root)的特權來運行一個命令。sudo有詳細的日誌功能，並且提供了對用户可通過sudo來運行哪些命令的細粒度控制。</p><h3 id="sudo-vs-su" tabindex="-1">Sudo vs. Su <a class="header-anchor" href="#sudo-vs-su" aria-label="Permalink to “Sudo vs. Su”">​</a></h3><p>su命令也提供了同樣的特權提升功能，兩者不同的是它們認證過程和特權變化的粒度。su允許你從你的登錄會話切換到另一個用户的會話，然後你可以隨心所欲地用該用户的特權來運行任何程序，但是你需要知道目標用户的密碼才能切換這個用户。而另一方面，sudo能在單個命令的基礎上工作，允許你用root的特權來運行單個命令。用sudo你不必一定要知道root的密碼，但是在提示輸入sudo密碼的時候要輸入你的密碼。</p><h3 id="在sudoers列表裏添加用户" tabindex="-1">在Sudoers列表裏添加用户 <a class="header-anchor" href="#在sudoers列表裏添加用户" aria-label="Permalink to “在Sudoers列表裏添加用户”">​</a></h3><p>作為一個新用户的你如果試圖運行sudo命令，你會碰到以下錯誤。意思是你不在這個包含經過認證就可以使用sudo特權的這麼一個用户組的sudoers列表裏。</p><pre><code>[my-user-id] is not in the sudoers file.  This incident will be reported.
</code></pre><p>有兩個方法可以把你加入到sudoers列表中去。</p><h3 id="方法一" tabindex="-1">方法一 <a class="header-anchor" href="#方法一" aria-label="Permalink to “方法一”">​</a></h3><p>第一個方法是把你添加到名為sudo的Linux用户組裏。這個特殊的Linux用户組是預配置來使用sudo的。因此，一旦你在這個組裏面，那你就可以運行sudo命令了。</p><p>以下命令會把你加入到Linux的sudo組裏，來確保讓你能作為root用户來運行命令。</p><pre><code># adduser &lt;用户名&gt; sudo
</code></pre><p>現在來確認你的組員資格有沒有更新，使用groups命令來看看你當前屬於哪個組的列表裏。這個列表必定是包含sudo組的。</p><pre><code>$ groups 
</code></pre><hr><pre><code>alice adm cdrom sudo dip plugdev fuse lpadmin netdev sambashare davfs2 libvirtd docker promiscuous
</code></pre><p>組員資格變動（和sudo訪問）會在你登出後重新登錄後生效。</p><h3 id="方法二" tabindex="-1">方法二 <a class="header-anchor" href="#方法二" aria-label="Permalink to “方法二”">​</a></h3><p>第二個能讓你使用sudo的方法是直接把你自己添加到 /etc/sudoers 這個配置文件中去。</p><p>要修改 /etc/sudoers 文件，你可以使用一個名為visudo的特殊sudo編輯器命令。用root身份簡單調用以下命令。</p><pre><code># visudo 
</code></pre><p>這條命令能打開並編輯 /etc/sudoers 文件，將以下這行文字添加至文件末尾，並按Ctrl+X。提示出現時，保存修改退出。</p><pre><code>&lt;username&gt; ALL=(ALL) ALL
</code></pre><p>這個修改會立即生效，你就能馬上使用sudo了。</p><p><img src="https://farm8.staticflickr.com/7511/15866443418_e147329e1b_c.jpg" alt=""></p><hr>`,27)),r("p",null,[e[1]||(e[1]=s("via: ",-1)),t(o,{href:"http://ask.xmodulo.com/fix-is-not-in-the-sudoers-file.html"},{default:i(()=>[...e[0]||(e[0]=[s("http://ask.xmodulo.com/fix-is-not-in-the-sudoers-file.html",-1)])]),_:1})]),r("p",null,[e[4]||(e[4]=s("譯者：",-1)),t(o,{href:"https://github.com/ZTinoZ"},{default:i(()=>[...e[2]||(e[2]=[s("ZTinoZ",-1)])]),_:1}),e[5]||(e[5]=s(" 校對：",-1)),t(o,{href:"https://github.com/wxy"},{default:i(()=>[...e[3]||(e[3]=[s("wxy",-1)])]),_:1})]),r("p",null,[e[8]||(e[8]=s("本文由 ",-1)),t(o,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[6]||(e[6]=[s("LCTT",-1)])]),_:1}),e[9]||(e[9]=s(" 原創翻譯，",-1)),t(o,{href:"http://linux.cn/"},{default:i(()=>[...e[7]||(e[7]=[s("Linux中國",-1)])]),_:1}),e[10]||(e[10]=s(" 榮譽推出",-1))])])}const b=n(p,[["render",f]]);export{c as __pageData,b as default};
